/**
 * The per-country string entrypoints ship no type declarations. Each one is a
 * default-exported SVG markup string (3:2 aspect ratio).
 */
declare module 'country-flag-icons/string/3x2/*' {
  const svg: string;
  export default svg;
}

declare module 'country-flag-icons/string/1x1/*' {
  const svg: string;
  export default svg;
}
